use axum::extract::{Extension, Json, State};

use application::{
    dto::{ConfirmTotpSetupRequest, ConfirmTotpSetupResponse},
    use_cases::ConfirmTotpSetupUseCase,
};
use domain::shared::types::AuthenticatedUser;

use crate::{auth_state::AuthState, error::ApiError};

/// `POST /auth/totp/confirm` — behind `jwt_auth`. Finishes TOTP 2FA
/// enrollment: verifies the user's first code against the secret
/// generated by `POST /auth/totp/enable`, then permanently turns 2FA on
/// for the account and returns 10 backup codes (shown exactly once).
pub async fn confirm_totp(
    State(state): State<AuthState>,
    Extension(authenticated_user): Extension<AuthenticatedUser>,
    Json(payload): Json<ConfirmTotpSetupRequest>,
) -> Result<Json<ConfirmTotpSetupResponse>, ApiError> {
    let use_case = ConfirmTotpSetupUseCase::new(
        state.user_repository.clone(),
        state.secret_cipher.clone(),
        state.password_hasher.clone(),
        state.pending_auth_cache.clone(),
        state.backup_code_repository.clone(),
        state.id_generator.clone(),
    );

    let response = use_case
        .execute(authenticated_user.user_id(), payload)
        .await
        .map_err(|err| ApiError::bad_request(err.to_string()))?;

    Ok(Json(response))
}
